use std::env;

pub const VERSION: &str = "1.0.0-alpha.70";

#[derive(Default, Debug)]
pub struct Args {
    pub inputs: Vec<String>,
    pub output_file: Option<String>,
    pub output_dir: Option<String>,
    pub minify: bool,
    pub bundle: bool,
    pub browserslist: bool,
    pub targets: Option<String>,
    pub sourcemap: bool,
    pub css_modules: bool,
    pub css_modules_file: Option<String>,
    pub css_modules_dashed_idents: bool,
    pub css_modules_pattern: Option<String>,
    pub custom_media: bool,
    pub error_recovery: bool,
    pub show_help: bool,
    pub show_version: bool,
}

pub fn parse_args() -> Result<Args, String> {
    let raw: Vec<String> = env::args().skip(1).collect();
    let mut args = Args::default();
    let mut i = 0;
    while i < raw.len() {
        let a = &raw[i];
        match a.as_str() {
            "-h" | "--help" => args.show_help = true,
            "-V" | "--version" => args.show_version = true,
            "-m" | "--minify" => args.minify = true,
            "--bundle" => args.bundle = true,
            "--browserslist" => args.browserslist = true,
            "--sourcemap" => args.sourcemap = true,
            "--custom-media" => args.custom_media = true,
            "--error-recovery" => args.error_recovery = true,
            "--css-modules-dashed-idents" => args.css_modules_dashed_idents = true,
            "-o" | "--output-file" => {
                i += 1;
                if i >= raw.len() { return Err(format!("Missing value for {}", a)); }
                args.output_file = Some(raw[i].clone());
            }
            "-d" | "--output-dir" => {
                i += 1;
                if i >= raw.len() { return Err(format!("Missing value for {}", a)); }
                args.output_dir = Some(raw[i].clone());
            }
            "-t" | "--targets" => {
                i += 1;
                if i >= raw.len() { return Err(format!("Missing value for {}", a)); }
                args.targets = Some(raw[i].clone());
            }
            "--css-modules-pattern" => {
                i += 1;
                if i >= raw.len() { return Err(format!("Missing value for {}", a)); }
                args.css_modules_pattern = Some(raw[i].clone());
            }
            "--css-modules" => {
                args.css_modules = true;
                // optional next arg that doesn't start with '-'
                if i + 1 < raw.len() && !raw[i+1].starts_with('-') {
                    // Only treat as value if it's not a file we'd consider input.
                    // Lightning CSS's --css-modules takes an optional value.
                    // Heuristic: if next token looks like a json filename, take it.
                    let next = &raw[i+1];
                    if next.ends_with(".json") {
                        args.css_modules_file = Some(next.clone());
                        i += 1;
                    }
                }
            }
            s if s.starts_with("--css-modules=") => {
                args.css_modules = true;
                args.css_modules_file = Some(s["--css-modules=".len()..].to_string());
            }
            s if s.starts_with("--output-file=") => {
                args.output_file = Some(s["--output-file=".len()..].to_string());
            }
            s if s.starts_with("--output-dir=") => {
                args.output_dir = Some(s["--output-dir=".len()..].to_string());
            }
            s if s.starts_with("--targets=") => {
                args.targets = Some(s["--targets=".len()..].to_string());
            }
            s if s.starts_with("--css-modules-pattern=") => {
                args.css_modules_pattern = Some(s["--css-modules-pattern=".len()..].to_string());
            }
            s if s.starts_with("-") && s.len() > 1 => {
                return Err(format!("error: Found argument '{}' which wasn't expected", s));
            }
            _ => {
                args.inputs.push(a.clone());
            }
        }
