// Simple CSS tokenizer

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Ident(String),
    AtKeyword(String),   // @media etc (without @)
    Hash(String),        // #id or #rrggbb
    String(String, char),// content, quote used
    Number(String),
    Dimension(String, String), // value, unit
    Percentage(String),
    Function(String),    // url(, calc( etc - name without (
    Url(String),         // bare url(...) contents
    Whitespace,
    Comment(String),
    Colon,
    Semicolon,
    Comma,
    LBrace,
    RBrace,
    LBracket,
    RBracket,
    LParen,
    RParen,
    Delim(char),
    Cdo,    // <!--
    Cdc,    // -->
    IncludeMatch,    // ~=
    DashMatch,       // |=
    PrefixMatch,     // ^=
    SuffixMatch,     // $=
    SubstringMatch,  // *=
    Column,          // ||
    Eof,
}

pub struct Tokenizer<'a> {
    input: &'a [u8],
    pos: usize,
}

pub fn tokenize(input: &str) -> Vec<Token> {
    let mut t = Tokenizer { input: input.as_bytes(), pos: 0 };
    let mut out = Vec::new();
    loop {
        let tok = t.next_token();
        let is_eof = matches!(tok, Token::Eof);
        out.push(tok);
        if is_eof { break; }
    }
    out
}

impl<'a> Tokenizer<'a> {
    fn peek(&self, off: usize) -> Option<u8> {
        self.input.get(self.pos + off).copied()
    }
    fn bump(&mut self) -> Option<u8> {
        let b = self.input.get(self.pos).copied();
        if b.is_some() { self.pos += 1; }
        b
    }

    fn next_token(&mut self) -> Token {
        if self.pos >= self.input.len() { return Token::Eof; }
        let c = self.input[self.pos];

        // Whitespace
        if is_ws(c) {
            while self.pos < self.input.len() && is_ws(self.input[self.pos]) { self.pos += 1; }
            return Token::Whitespace;
        }

        // Comment
        if c == b'/' && self.peek(1) == Some(b'*') {
            self.pos += 2;
            let start = self.pos;
            while self.pos < self.input.len() {
                if self.input[self.pos] == b'*' && self.peek(1) == Some(b'/') {
                    let text = std::str::from_utf8(&self.input[start..self.pos]).unwrap_or("").to_string();
                    self.pos += 2;
                    return Token::Comment(text);
                }
                self.pos += 1;
            }
            let text = std::str::from_utf8(&self.input[start..self.pos]).unwrap_or("").to_string();
            return Token::Comment(text);
        }

        // String
        if c == b'"' || c == b'\'' {
            return self.consume_string(c);
        }

        // Hash
        if c == b'#' {
            self.pos += 1;
            if self.pos < self.input.len() && (is_ident_char(self.input[self.pos]) || self.input[self.pos] == b'-' || self.input[self.pos] == b'\\') {
                let name = self.consume_ident_like();
                return Token::Hash(name);
            }
            return Token::Delim('#');
        }

        // Number-like
        if c.is_ascii_digit() || ((c == b'-' || c == b'+' || c == b'.') && self.looks_like_number()) {
            return self.consume_numeric();
        }

        // @-keyword
        if c == b'@' {
            self.pos += 1;
            if self.pos < self.input.len() && (is_ident_start(self.input[self.pos]) || self.input[self.pos] == b'-') {
                let name = self.consume_ident_like();
                return Token::AtKeyword(name);
            }
            return Token::Delim('@');
        }

        // Identifier-like (including functions and url)
        if is_ident_start(c) || c == b'-' || c == b'_' || c >= 0x80 || c == b'\\' {
            let name = self.consume_ident_like();
            if self.pos < self.input.len() && self.input[self.pos] == b'(' {
                self.pos += 1;
                if name.eq_ignore_ascii_case("url") {
                    // Check if it's url("...") - return as Function
                    let save = self.pos;
                    while self.pos < self.input.len() && is_ws(self.input[self.pos]) { self.pos += 1; }
                    if self.pos < self.input.len() && (self.input[self.pos] == b'"' || self.input[self.pos] == b'\'') {
                        self.pos = save;
                        return Token::Function(name);
                    }
                    // Bare url
                    return self.consume_url();
                }
                return Token::Function(name);
            }
            return Token::Ident(name);
        }

        // Match operators / delims
        match c {
            b':' => { self.pos += 1; Token::Colon }
            b';' => { self.pos += 1; Token::Semicolon }
            b',' => { self.pos += 1; Token::Comma }
            b'{' => { self.pos += 1; Token::LBrace }
            b'}' => { self.pos += 1; Token::RBrace }
            b'[' => { self.pos += 1; Token::LBracket }
            b']' => { self.pos += 1; Token::RBracket }
            b'(' => { self.pos += 1; Token::LParen }
            b')' => { self.pos += 1; Token::RParen }
            b'<' => {
                if self.peek(1) == Some(b'!') && self.peek(2) == Some(b'-') && self.peek(3) == Some(b'-') {
                    self.pos += 4; Token::Cdo
                } else { self.pos += 1; Token::Delim('<') }
            }
            b'-' => {
                if self.peek(1) == Some(b'-') && self.peek(2) == Some(b'>') {
                    self.pos += 3; Token::Cdc
                } else { self.pos += 1; Token::Delim('-') }
            }
            b'~' => {
                if self.peek(1) == Some(b'=') { self.pos += 2; Token::IncludeMatch } else { self.pos += 1; Token::Delim('~') }
            }
            b'|' => {
                if self.peek(1) == Some(b'=') { self.pos += 2; Token::DashMatch }
                else if self.peek(1) == Some(b'|') { self.pos += 2; Token::Column }
                else { self.pos += 1; Token::Delim('|') }
            }
            b'^' => {
                if self.peek(1) == Some(b'=') { self.pos += 2; Token::PrefixMatch } else { self.pos += 1; Token::Delim('^') }
            }
            b'$' => {
