use crate::tokenizer::Token;
use crate::css::*;

type TokList = [Token];

struct Parser<'a> {
    tokens: &'a TokList,
    pos: usize,
}

pub fn parse_stylesheet(tokens: &[Token]) -> Result<Stylesheet, String> {
    let mut p = Parser { tokens, pos: 0 };
    let rules = p.parse_rule_list(true)?;
    Ok(Stylesheet { rules })
}

impl<'a> Parser<'a> {
    fn peek(&self) -> &Token { &self.tokens[self.pos] }
    fn bump(&mut self) -> &Token {
        let t = &self.tokens[self.pos];
        if !matches!(t, Token::Eof) { self.pos += 1; }
        t
    }
    fn skip_ws_and_comments(&mut self) {
        while self.pos < self.tokens.len() {
            match &self.tokens[self.pos] {
                Token::Whitespace | Token::Comment(_) => self.pos += 1,
                _ => break,
            }
        }
    }

    fn parse_rule_list(&mut self, top_level: bool) -> Result<Vec<Rule>, String> {
        let mut rules = Vec::new();
        loop {
            self.skip_ws_and_comments();
            match self.peek() {
                Token::Eof => break,
                Token::RBrace if !top_level => break,
                Token::Cdo | Token::Cdc if top_level => { self.bump(); }
                Token::AtKeyword(_) => {
                    let r = self.parse_at_rule()?;
                    rules.push(Rule::AtRule(r));
                }
                _ => {
                    let r = self.parse_style_rule()?;
                    if let Some(r) = r { rules.push(Rule::Style(r)); }
                }
            }
        }
        Ok(rules)
    }

    fn parse_style_rule(&mut self) -> Result<Option<StyleRule>, String> {
        // Collect prelude until { or ;
        let mut prelude_tokens = Vec::new();
        loop {
            match self.peek() {
                Token::Eof => return Err("Unexpected end of input".to_string()),
                Token::LBrace => break,
                Token::Semicolon => {
                    self.bump();
                    return Ok(None);
                }
                _ => {
                    prelude_tokens.push(self.bump().clone());
                }
            }
        }
        // Consume {
        self.bump();
        let selectors = print_selector_list(&prelude_tokens);
        let declarations = self.parse_declaration_block()?;
        Ok(Some(StyleRule { selectors, declarations }))
    }

    fn parse_at_rule(&mut self) -> Result<AtRule, String> {
        let name = if let Token::AtKeyword(n) = self.bump() { n.clone() } else { unreachable!() };
        let mut prelude_tokens = Vec::new();
        loop {
            match self.peek() {
                Token::Eof => return Err("Unexpected end of input".to_string()),
                Token::LBrace => break,
                Token::Semicolon => {
                    self.bump();
                    return Ok(AtRule { name, prelude: format_prelude(&prelude_tokens), block: None });
                }
                _ => { prelude_tokens.push(self.bump().clone()); }
            }
        }
        self.bump(); // {
        // Decide block type by name
        let lname = name.to_ascii_lowercase();
        let block = match lname.as_str() {
            "media" | "supports" | "document" | "-moz-document" | "container" | "layer" | "scope" => {
                let rules = self.parse_rule_list(false)?;
                self.skip_ws_and_comments();
                if matches!(self.peek(), Token::RBrace) { self.bump(); }
                AtBlock::Rules(rules)
            }
            "font-face" | "page" | "counter-style" | "property" | "viewport" | "-ms-viewport" | "font-feature-values" => {
                let decls = self.parse_declaration_block()?;
                AtBlock::Declarations(decls)
            }
            "keyframes" | "-webkit-keyframes" | "-moz-keyframes" | "-o-keyframes" => {
                let frames = self.parse_keyframe_list()?;
                AtBlock::Keyframes(frames)
            }
            _ => {
                // Generic: try rule-list
                let rules = self.parse_rule_list(false)?;
                self.skip_ws_and_comments();
                if matches!(self.peek(), Token::RBrace) { self.bump(); }
                AtBlock::Rules(rules)
            }
        };
        Ok(AtRule { name, prelude: format_prelude(&prelude_tokens), block: Some(block) })
    }

    fn parse_keyframe_list(&mut self) -> Result<Vec<KeyframeRule>, String> {
        let mut frames = Vec::new();
        loop {
            self.skip_ws_and_comments();
            match self.peek() {
                Token::Eof => return Err("Unexpected end of input".to_string()),
                Token::RBrace => { self.bump(); break; }
                _ => {
                    let mut sel_tokens = Vec::new();
                    loop {
                        match self.peek() {
                            Token::Eof => return Err("Unexpected end of input".to_string()),
                            Token::LBrace => break,
                            _ => sel_tokens.push(self.bump().clone()),
                        }
                    }
                    self.bump(); // {
                    let sel = format_prelude(&sel_tokens).trim().to_string();
                    let decls = self.parse_declaration_block()?;
                    frames.push(KeyframeRule { selector: sel, declarations: decls });
                }
            }
        }
        Ok(frames)
    }

    fn parse_declaration_block(&mut self) -> Result<Vec<Declaration>, String> {
        let mut decls = Vec::new();
        loop {
            self.skip_ws_and_comments();
            match self.peek() {
                Token::Eof => return Err("Unexpected end of input".to_string()),
                Token::RBrace => { self.bump(); break; }
                Token::Semicolon => { self.bump(); }
                _ => {
                    if let Some(d) = self.parse_declaration()? { decls.push(d); }
                }
            }
        }
        Ok(decls)
    }

    fn parse_declaration(&mut self) -> Result<Option<Declaration>, String> {
        // name is an ident
        let name = match self.peek() {
            Token::Ident(s) => s.clone(),
            _ => {
                // Skip until ; or }
                while !matches!(self.peek(), Token::Semicolon | Token::RBrace | Token::Eof) {
                    self.bump();
                }
                return Ok(None);
            }
        };
        self.bump();
        self.skip_ws_and_comments();
        if !matches!(self.peek(), Token::Colon) {
            while !matches!(self.peek(), Token::Semicolon | Token::RBrace | Token::Eof) {
                self.bump();
            }
            return Ok(None);
        }
        self.bump(); // :
        // Collect value tokens until ; or }
        let mut val_tokens = Vec::new();
        let mut depth = 0usize;
        loop {
            match self.peek() {
                Token::Eof => break,
                Token::Semicolon if depth == 0 => break,
                Token::RBrace if depth == 0 => break,
                Token::LParen | Token::LBracket | Token::Function(_) => {
                    depth += 1;
                    val_tokens.push(self.bump().clone());
                }
                Token::RParen | Token::RBracket => {
                    if depth > 0 { depth -= 1; }
                    val_tokens.push(self.bump().clone());
                }
                _ => val_tokens.push(self.bump().clone()),
            }
        }
        // Check trailing !important
        let (value, important) = extract_important(&val_tokens);
        Ok(Some(Declaration { name, value, important }))
    }
}

fn extract_important(tokens: &[Token]) -> (String, bool) {
    // Strip trailing whitespace/comments
    let mut end = tokens.len();
    while end > 0 && matches!(tokens[end-1], Token::Whitespace | Token::Comment(_)) { end -= 1; }
    // Look for ident "important" preceded by !
    if end >= 2 {
        if let Token::Ident(s) = &tokens[end-1] {
            if s.eq_ignore_ascii_case("important") {
                // find ! before it (possibly with ws)
                let mut i = end - 1;
                while i > 0 && matches!(tokens[i-1], Token::Whitespace | Token::Comment(_)) { i -= 1; }
                if i > 0 {
                    if let Token::Delim('!') = &tokens[i-1] {
                        let val = format_value(&tokens[0..i-1]);
                        return (val, true);
                    }
                }
            }
        }
    }
    (format_value(&tokens[0..end]), false)
}

// Format a selector list with spaces collapsed and comma-space separation
fn print_selector_list(tokens: &[Token]) -> String {
    // Compress whitespace between tokens
    let mut out = String::new();
    let mut prev_was_ws = true;
    let mut at_start = true;
    for t in tokens {
        match t {
            Token::Whitespace => {
                if !at_start { prev_was_ws = true; }
            }
            Token::Comment(_) => {}
            Token::Comma => {
                // trim preceding ws
                while out.ends_with(' ') { out.pop(); }
                out.push_str(", ");
                prev_was_ws = false;
                at_start = false;
            }
            _ => {
                if prev_was_ws && !at_start { out.push(' '); }
                out.push_str(&token_to_src(t));
                prev_was_ws = false;
                at_start = false;
            }
        }
    }
    while out.ends_with(' ') { out.pop(); }
    // Normalize :before/:after to colon form (CSS2 -> kept as single colon)
    // Also convert ::before -> :before per output we observed
    let out = normalize_pseudo(&out);
    out
}

fn normalize_pseudo(s: &str) -> String {
    // Replace ::before -> :before, ::after -> :after, ::first-line -> :first-line, etc.
    let single_colon_pseudos = ["before", "after", "first-line", "first-letter"];
    let mut result = s.to_string();
    for p in single_colon_pseudos.iter() {
        let from = format!("::{}", p);
        let to = format!(":{}", p);
        result = result.replace(&from, &to);
    }
    result
}

// Format a declaration value: collapse whitespace, keep significant formatting
pub fn format_value(tokens: &[Token]) -> String {
    // Trim leading/trailing whitespace/comments
    let mut start = 0;
    let mut end = tokens.len();
    while start < end && matches!(tokens[start], Token::Whitespace | Token::Comment(_)) { start += 1; }
    while end > start && matches!(tokens[end-1], Token::Whitespace | Token::Comment(_)) { end -= 1; }

    let mut out = String::new();
    let mut prev_was_ws = false;
    for i in start..end {
        let t = &tokens[i];
        match t {
            Token::Whitespace => { prev_was_ws = true; }
            Token::Comment(_) => {}
            Token::Comma => {
                while out.ends_with(' ') { out.pop(); }
                out.push_str(", ");
                prev_was_ws = false;
            }
            _ => {
                if prev_was_ws && !out.is_empty() { out.push(' '); }
                out.push_str(&token_to_src(t));
                prev_was_ws = false;
            }
        }
    }
    out
}

pub fn format_prelude(tokens: &[Token]) -> String {
    // Similar to format_value but trim trailing ws
    let mut start = 0;
    let mut end = tokens.len();
    while start < end && matches!(tokens[start], Token::Whitespace | Token::Comment(_)) { start += 1; }
    while end > start && matches!(tokens[end-1], Token::Whitespace | Token::Comment(_)) { end -= 1; }

    let mut out = String::new();
    let mut prev_was_ws = false;
    for i in start..end {
        let t = &tokens[i];
        match t {
            Token::Whitespace => { prev_was_ws = true; }
            Token::Comment(_) => {}
            Token::Comma => {
                while out.ends_with(' ') { out.pop(); }
                out.push_str(", ");
                prev_was_ws = false;
            }
            _ => {
                if prev_was_ws && !out.is_empty() { out.push(' '); }
                out.push_str(&token_to_src(t));
                prev_was_ws = false;
            }
        }
    }
    out
}

pub fn token_to_src(t: &Token) -> String {
    match t {
        Token::Ident(s) => s.clone(),
        Token::AtKeyword(s) => format!("@{}", s),
        Token::Hash(s) => format!("#{}", s),
        Token::String(s, q) => {
            let mut out = String::new();
            out.push(*q);
            for c in s.chars() {
                if c == *q { out.push('\\'); out.push(c); }
                else if c == '\\' { out.push_str("\\\\"); }
                else { out.push(c); }
            }
            out.push(*q);
            out
        }
        Token::Number(n) => n.clone(),
        Token::Dimension(n, u) => format!("{}{}", n, u),
        Token::Percentage(n) => format!("{}%", n),
        Token::Function(n) => format!("{}(", n),
        Token::Url(s) => format!("url({})", s),
        Token::Whitespace => " ".to_string(),
        Token::Comment(s) => format!("/*{}*/", s),
        Token::Colon => ":".to_string(),
        Token::Semicolon => ";".to_string(),
        Token::Comma => ",".to_string(),
        Token::LBrace => "{".to_string(),
        Token::RBrace => "}".to_string(),
        Token::LBracket => "[".to_string(),
        Token::RBracket => "]".to_string(),
        Token::LParen => "(".to_string(),
        Token::RParen => ")".to_string(),
        Token::Delim(c) => c.to_string(),
        Token::Cdo => "<!--".to_string(),
        Token::Cdc => "-->".to_string(),
        Token::IncludeMatch => "~=".to_string(),
        Token::DashMatch => "|=".to_string(),
        Token::PrefixMatch => "^=".to_string(),
        Token::SuffixMatch => "$=".to_string(),
        Token::SubstringMatch => "*=".to_string(),
        Token::Column => "||".to_string(),
        Token::Eof => String::new(),
    }
}
