// Normalize a color value token representation to lightningcss's canonical form
// Input: a string like "#ffffff" or "red" or "rgb(...)". Returns the best representation.
pub fn minify_color(s: &str) -> String {
    let trimmed = s.trim();
    // Hex
    if let Some(rest) = trimmed.strip_prefix('#') {
        if rest.chars().all(|c| c.is_ascii_hexdigit()) {
            return normalize_hex(rest);
        }
    }
    // Named color
    if let Some(hex) = color_name_to_hex(trimmed) {
        let hex_str = format!("#{}", hex);
        if hex_str.len() < trimmed.len() { return hex_str; }
        return trimmed.to_string();
    }
    trimmed.to_string()
}

