# Add helper functions at end of file
text += '''

pub fn normalize_number(n: &str) -> String {
    // Parse the number, strip leading 0 before decimal, strip trailing zeros after decimal, strip trailing dot
    let s = n.trim();
    let (sign, rest) = if let Some(r) = s.strip_prefix('-') {
        ("-", r)
    } else if let Some(r) = s.strip_prefix('+') {
        ("", r)
    } else {
        ("", s)
    };

    // Check for exponent
    let (main, exp) = if let Some(idx) = rest.find(|c: char| c == 'e' || c == 'E') {
        (&rest[..idx], &rest[idx..])
    } else {
        (rest, "")
    };

    let (int_part, frac_part) = if let Some(idx) = main.find('.') {
        (&main[..idx], &main[idx+1..])
    } else {
        (main, "")
    };

    // Strip trailing zeros from fraction
    let frac_stripped = frac_part.trim_end_matches('0');
    // Strip leading zeros from int_part (but keep at least one)
    let int_stripped = int_part.trim_start_matches('0');
    let int_final = if int_stripped.is_empty() { "" } else { int_stripped };

    let mut out = String::new();
    out.push_str(sign);
    if frac_stripped.is_empty() {
        // Integer
        if int_final.is_empty() {
            out.push('0');
        } else {
            out.push_str(int_final);
        }
    } else {
        // Has fractional part
        if int_final.is_empty() {
            // ".5" form (drop leading zero)
            out.push('.');
            out.push_str(frac_stripped);
        } else {
            out.push_str(int_final);
            out.push('.');
            out.push_str(frac_stripped);
        }
